const item = $input.first().json;
const content = item.message?.content;
if (typeof content !== 'string') {
  throw new Error('Ollama no devolvió message.content. Revisa el nodo HTTP Request.');
}
let generated;
try {
  generated = JSON.parse(content);
} catch (error) {
  throw new Error('La respuesta de Ollama no es JSON válido: ' + error.message + '. Respuesta: ' + content.slice(0, 500));
}
const candidates = [
  generated.video_prompt,
  generated.videoPrompt,
  generated.image_prompt,
  generated.visual_prompt,
  generated.prompt
];
let prompt = candidates.find(value => typeof value === 'string' && value.trim());
if (!prompt && typeof generated.scene === 'string' && generated.scene.trim()) {
  prompt = `dark fantasy gothic landscape, ${generated.scene.trim()}, cinematic moody lighting, vertical portrait composition, layered foreground middle ground and background, atmospheric fog, highly detailed environment, no people, no creatures, no text, no logo`;
}
if (!prompt) {
  const keys = Object.keys(generated).join(', ') || '(ninguna)';
  throw new Error('Ollama devolvió JSON, pero no encontré video_prompt, prompt ni scene. Claves recibidas: ' + keys + '. Respuesta: ' + content.slice(0, 500));
}
return [{ json: { promptBase64: Buffer.from(prompt.trim(), 'utf8').toString('base64') } }];

